shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ece6d9;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #294057;
    --crimson: #8f241e;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-family: 'Lora', 'Noto Serif SC', Georgia, serif;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  /* Strict Bilingual Visibility Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    background-color: var(--paper);
    overflow-x: hidden;
    position: relative;
  }

  /* Reading Progress Bar */
  .progress-bar {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    background: var(--accent);
    width: 0%;
    z-index: 1001;
    transition: width 0.1s ease-out;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.96);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--line-strong);
    padding: 0.7rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-cluster {
    display: flex;
    align-items: center;
    gap: 0.85rem;
  }

  .wsj-monogram {
    font-family: 'Playfair Display', Georgia, serif;
    font-weight: 800;
    font-size: 1.25rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-decoration: none;
  }

  .masthead-divider {
    width: 1px;
    height: 16px;
    background: var(--line-strong);
  }

  .section-tag {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
  }

  .masthead-meta {
    display: flex;
    align-items: center;
    gap: 1rem;
  }

  .edition-badge {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.7rem;
    color: var(--muted);
    letter-spacing: 0.04em;
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.3rem 0.65rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.74rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.15s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero {
    max-width: 1120px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 3px double var(--line-strong);
  }

  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--crimson);
  }

  .kicker-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--crimson);
    display: inline-block;
  }

  .hero-title {
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-weight: 800;
    font-size: clamp(2.15rem, 4.4vw, 3.6rem);
    line-height: 1.16;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.25rem;
    max-width: 960px;
  }

  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.26;
    letter-spacing: 0.01em;
  }

  .hero-dek {
    font-family: 'Lora', 'Noto Serif SC', Georgia, serif;
    font-size: clamp(1.12rem, 1.8vw, 1.38rem);
    line-height: 1.55;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 2rem;
    font-weight: 400;
  }

  .hero-byline-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1.25rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    color: var(--muted);
  }

  .byline-authors strong {
    color: var(--ink);
    font-weight: 600;
  }

  .byline-date {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.76rem;
    color: var(--muted);
  }

  /* Reporter's Context Dossier Banner */
  .dossier-strip {
    max-width: 1120px;
    margin: 2rem auto 0;
    padding: 0 1.5rem;
  }

  .dossier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--accent);
    padding: 1.35rem 1.6rem;
    display: grid;
    grid-template-columns: 190px 1fr;
    gap: 1.5rem;
    align-items: start;
  }

  .dossier-label {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    line-height: 1.4;
  }

  .dossier-label span.sub {
    display: block;
    font-weight: 400;
    color: var(--muted);
    margin-top: 0.3rem;
    font-size: 0.68rem;
  }

  .dossier-content {
    font-family: 'Noto Sans SC', 'Inter', sans-serif;
    font-size: 0.92rem;
    line-height: 1.72;
    color: var(--body);
  }

  /* Main Editorial Container & Asymmetric Rails */
  .editorial-shell {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 4rem;
  }

  .chapter-block {
    margin-bottom: 3.5rem;
  }

  .chapter-header {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin: 2.5rem 0 1.75rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--ink);
  }

  .chapter-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--paper);
    background: var(--ink);
    padding: 0.2rem 0.55rem;
    letter-spacing: 0.06em;
  }

  .chapter-title {
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.01em;
  }

  .rail-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(260px, 340px);
    justify-content: space-between;
    gap: 3rem;
    align-items: start;
  }

  .prose-col {
    min-width: 0;
  }

  .side-rail {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
    position: sticky;
    top: 4.5rem;
  }

  /* Typography & Prose */
  .prose-p {
    font-family: 'Lora', 'Noto Serif SC', Georgia, serif;
    font-size: 1.09rem;
    line-height: 1.88;
    color: var(--body);
    margin-bottom: 1.45rem;
  }

  :host([lang="zh-CN"]) .prose-p {
    font-size: 1.08rem;
    line-height: 1.94;
    text-align: justify;
  }

  /* Lead Paragraph Treatment (No CSS ::first-letter on Chinese) */
  .lead-p {
    font-size: 1.22rem !important;
    line-height: 1.78 !important;
    color: var(--ink);
    font-weight: 600;
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.75rem;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 0.12em;
    font-weight: 600;
  }

  /* Audio Recording Transcript Callout (Primary Flow Split) */
  .audio-evidence-box {
    background: var(--navy-bg);
    color: #f4f1ea;
    padding: 1.65rem 1.85rem;
    margin: 1.75rem 0;
    border-left: 4px solid var(--accent);
    position: relative;
  }

  .audio-evidence-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.9rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--navy-line);
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #e09f67;
  }

  .waveform-bars {
    display: inline-flex;
    align-items: center;
    gap: 3px;
  }

  .waveform-bars span {
    display: inline-block;
    width: 2px;
    background: #e09f67;
  }

  .audio-quote-text {
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-size: 1.24rem;
    line-height: 1.58;
    color: #ffffff;
    margin-bottom: 0.75rem;
  }

  .audio-quote-sub {
    font-family: 'Lora', 'Noto Serif SC', Georgia, serif;
    font-size: 1.02rem;
    line-height: 1.65;
    color: #d5cfc2;
  }

  /* Side Rail Derived Callouts */
  .pull-quote {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.35rem 1.25rem;
  }

  .pull-quote .quote-text {
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-size: 1.08rem;
    line-height: 1.58;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0.75rem;
  }

  .pull-quote .quote-attrib {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Forensic Dossier Note in Sidebar */
  .forensic-card {
    background: var(--paper);
    border: 1px solid var(--line-strong);
    padding: 1.25rem;
  }

  .forensic-card-title {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    margin-bottom: 0.85rem;
    padding-bottom: 0.45rem;
    border-bottom: 1px solid var(--line);
  }

  .forensic-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
  }

  .forensic-list li {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    line-height: 1.55;
    color: var(--body);
  }

  .forensic-list strong {
    display: block;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0.15rem;
  }

  /* Bespoke SVG Diagram Exhibit */
  .exhibit-panel {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 2rem 1.75rem;
    margin: 2.75rem 0;
  }

  .exhibit-head {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: baseline;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid var(--line-strong);
  }

  .exhibit-kicker {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
  }

  .exhibit-title {
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-size: 1.32rem;
    font-weight: 700;
    color: var(--ink);
    margin-top: 0.25rem;
  }

  .exhibit-sub {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.84rem;
    color: var(--muted);
  }

  .svg-wrapper {
    width: 100%;
    overflow: hidden;
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 0.5rem;
  }

  .exhibit-caption {
    margin-top: 0.85rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    color: var(--muted);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  /* Official Response Dossier Box (p11-p14 in order) */
  .response-dossier {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.75rem;
    margin: 2rem 0;
  }

  .response-dossier-header {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--ink);
    margin-bottom: 1.25rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .response-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.25rem;
  }

  .response-item {
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 1.15rem 1.25rem;
  }

  .response-entity {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--accent);
    margin-bottom: 0.5rem;
  }

  .response-item .prose-p {
    font-size: 0.96rem;
    line-height: 1.72;
    margin-bottom: 0.65rem;
  }

  .response-item .prose-p:last-child {
    margin-bottom: 0;
  }

  /* Metric Card (Derived m1) */
  .metric-card {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.5rem 1.35rem;
    border-top: 3px solid var(--accent);
  }

  .metric-card .metric-val {
    font-family: 'JetBrains Mono', 'Noto Serif SC', monospace;
    font-size: 2.2rem;
    font-weight: 700;
    color: #e09f67;
    line-height: 1.15;
    margin-bottom: 0.4rem;
  }

  .metric-card .metric-lbl {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #ffffff;
    margin-bottom: 0.65rem;
  }

  .metric-card .metric-note {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.8rem;
    line-height: 1.55;
    color: #c6bfb3;
  }

  /* Political Fallout Quote Box (p23 split) */
  .verdict-quote {
    background: var(--paper-card);
    border-left: 4px solid var(--crimson);
    padding: 1.4rem 1.65rem;
    margin: 1.5rem 0;
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-size: 1.14rem;
    line-height: 1.68;
    color: var(--ink);
  }

  /* Footer */
  .ed-footer {
    border-top: 2px solid var(--ink);
    background: var(--paper-card);
    padding: 2.5rem 1.5rem;
    margin-top: 3rem;
  }

  .ed-footer-inner {
    max-width: 1120px;
    margin: 0 auto;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.78rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow (<= 860px & 390px) */
  @media (max-width: 860px) {
    .rail-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .side-rail {
      position: static;
    }
    .dossier-box {
      grid-template-columns: 1fr;
      gap: 0.75rem;
    }
    .response-grid {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 480px) {
    .masthead {
      padding: 0.6rem 1rem;
    }
    .edition-badge {
      display: none;
    }
    .hero {
      padding: 2.25rem 1rem 1.75rem;
    }
    .dossier-strip {
      padding: 0 1rem;
    }
    .editorial-shell {
      padding: 1.75rem 1rem 3rem;
    }
    .exhibit-panel {
      padding: 1.25rem 1rem;
    }
    .audio-evidence-box {
      padding: 1.25rem 1.15rem;
    }
  }
